import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const POSITIONS = ['기자', '수습기자', '편집장', '부편집장'];

function ProfileModal({ onClose }) {
  const { user, updateProfile } = useAuth();
  const [form, setForm] = useState({ name: '', nickname: '', email: '', position: '' });
  const [saving, setSaving] = useState(false);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (user) {
      setForm({
        name:     user.name     || '',
        nickname: user.nickname || '',
        email:    user.email    || '',
        position: user.position || '',
      });
    }
  }, [user]);

  const validate = () => {
    const e = {};
    if (!form.name.trim())  e.name  = '이름을 입력해주세요.';
    if (!form.email.trim()) e.email = '이메일을 입력해주세요.';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) e.email = '올바른 이메일 형식이 아닙니다.';
    return e;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const errs = validate();
    if (Object.keys(errs).length > 0) { setErrors(errs); return; }
    setSaving(true);
    const result = await updateProfile({
      name:     form.name.trim(),
      nickname: form.nickname.trim() || form.name.trim(),
      email:    form.email.trim(),
      position: form.position || null,
    });
    setSaving(false);
    if (result.success) onClose();
  };

  const handleChange = (field, value) => {
    setForm(prev => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: undefined }));
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div
        className="modal-content"
        style={{ maxWidth: '420px', width: '90%' }}
        onClick={e => e.stopPropagation()}
      >
        {/* 헤더 */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '24px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ width: '36px', height: '36px', background: '#003580', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontWeight: 700, fontSize: '15px' }}>
              {user?.name?.charAt(0)}
            </div>
            <div>
              <h2 style={{ fontSize: '17px', fontWeight: 900, color: '#111' }}>프로필 수정</h2>
              <p style={{ fontSize: '12px', color: '#9ca3af', marginTop: '1px' }}>이름 · 이메일 · 직책을 변경합니다</p>
            </div>
          </div>
          <button
            onClick={onClose}
            style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '18px', color: '#9ca3af', lineHeight: 1 }}
          >✕</button>
        </div>

        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>

          {/* 이름 */}
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#374151', marginBottom: '6px', letterSpacing: '0.3px' }}>
              이름 <span style={{ color: '#d32f2f' }}>*</span>
            </label>
            <input
              type="text"
              value={form.name}
              onChange={e => handleChange('name', e.target.value)}
              placeholder="홍길동"
              style={{
                width: '100%', padding: '10px 14px',
                border: `1.5px solid ${errors.name ? '#d32f2f' : '#e5e7eb'}`,
                borderRadius: '8px', fontSize: '14px', outline: 'none',
                transition: 'border-color 0.15s',
                boxSizing: 'border-box',
              }}
              onFocus={e => e.target.style.borderColor = '#003580'}
              onBlur={e => e.target.style.borderColor = errors.name ? '#d32f2f' : '#e5e7eb'}
            />
            {errors.name && <p style={{ fontSize: '11px', color: '#d32f2f', marginTop: '4px' }}>{errors.name}</p>}
          </div>

          {/* 닉네임 */}
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#374151', marginBottom: '6px', letterSpacing: '0.3px' }}>
              닉네임
            </label>
            <input
              type="text"
              value={form.nickname}
              onChange={e => handleChange('nickname', e.target.value)}
              placeholder="표시될 이름 (비워두면 이름과 동일)"
              style={{
                width: '100%', padding: '10px 14px',
                border: '1.5px solid #e5e7eb',
                borderRadius: '8px', fontSize: '14px', outline: 'none',
                transition: 'border-color 0.15s',
                boxSizing: 'border-box',
              }}
              onFocus={e => e.target.style.borderColor = '#003580'}
              onBlur={e => e.target.style.borderColor = '#e5e7eb'}
            />
            <p style={{ fontSize: '11px', color: '#9ca3af', marginTop: '4px' }}>사이트에 표시되는 이름입니다. 비워두면 이름과 동일하게 적용됩니다.</p>
          </div>

          {/* 이메일 */}
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#374151', marginBottom: '6px', letterSpacing: '0.3px' }}>
              이메일 <span style={{ color: '#d32f2f' }}>*</span>
            </label>
            <input
              type="email"
              value={form.email}
              onChange={e => handleChange('email', e.target.value)}
              placeholder="example@daejin.ac.kr"
              style={{
                width: '100%', padding: '10px 14px',
                border: `1.5px solid ${errors.email ? '#d32f2f' : '#e5e7eb'}`,
                borderRadius: '8px', fontSize: '14px', outline: 'none',
                transition: 'border-color 0.15s',
                boxSizing: 'border-box',
              }}
              onFocus={e => e.target.style.borderColor = '#003580'}
              onBlur={e => e.target.style.borderColor = errors.email ? '#d32f2f' : '#e5e7eb'}
            />
            {errors.email && <p style={{ fontSize: '11px', color: '#d32f2f', marginTop: '4px' }}>{errors.email}</p>}
          </div>

          {/* 직책 */}
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 700, color: '#374151', marginBottom: '6px', letterSpacing: '0.3px' }}>
              직책
            </label>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '8px' }}>
              {POSITIONS.map(pos => (
                <button
                  key={pos}
                  type="button"
                  onClick={() => handleChange('position', form.position === pos ? '' : pos)}
                  style={{
                    padding: '9px 0',
                    border: `1.5px solid ${form.position === pos ? '#003580' : '#e5e7eb'}`,
                    borderRadius: '8px',
                    fontSize: '13px',
                    fontWeight: form.position === pos ? 700 : 500,
                    color: form.position === pos ? '#003580' : '#6b7280',
                    background: form.position === pos ? '#eff6ff' : '#fff',
                    cursor: 'pointer',
                    transition: 'all 0.15s',
                  }}
                >
                  {pos}
                </button>
              ))}
            </div>
            <p style={{ fontSize: '11px', color: '#9ca3af', marginTop: '6px' }}>선택 사항 — 다시 누르면 해제됩니다</p>
          </div>

          {/* 버튼 */}
          <div style={{ display: 'flex', gap: '10px', marginTop: '4px' }}>
            <button
              type="button"
              onClick={onClose}
              style={{
                flex: 1, padding: '11px 0',
                border: '1.5px solid #e5e7eb', borderRadius: '8px',
                fontSize: '14px', fontWeight: 600, color: '#6b7280',
                background: '#fff', cursor: 'pointer', transition: 'all 0.15s',
              }}
              onMouseEnter={e => e.target.style.background = '#f9fafb'}
              onMouseLeave={e => e.target.style.background = '#fff'}
            >
              취소
            </button>
            <button
              type="submit"
              disabled={saving}
              style={{
                flex: 2, padding: '11px 0',
                border: 'none', borderRadius: '8px',
                fontSize: '14px', fontWeight: 700, color: '#fff',
                background: saving ? '#9ca3af' : '#003580',
                cursor: saving ? 'not-allowed' : 'pointer',
                transition: 'background 0.15s',
                display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px',
              }}
              onMouseEnter={e => { if (!saving) e.target.style.background = '#002468'; }}
              onMouseLeave={e => { if (!saving) e.target.style.background = '#003580'; }}
            >
              {saving && <i className="fas fa-spinner fa-spin" style={{ fontSize: '12px' }}></i>}
              {saving ? '저장 중...' : '저장하기'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default ProfileModal;
